genereti_widget_values.guide:
{
  "format": "genereti-guide",
  "version": 1,
  "id": "genereticore-05-genereti-palette",
  "title": "A model chooses an artwork palette",
  "summary": "Learn on this editable graph. Inference starts only when you press Run.",
  "steps": [
    {
      "title": "Start the scene",
      "text": "ꘇ livecode · moving circle · press editor Run\n\nThe saved artwork starts on open, with paletteHue at 210 (blue).",
      "target": {
        "nodeType": "GeneretiLivecode",
        "nodeId": 4,
        "ref": "264194f7-9217-53a8-ad41-fbbba610954d",
        "part": "code"
      },
      "hint": "Follow the note at the top of the workflow. Top Run updates connected nodes."
    },
    {
      "title": "Ask for a palette",
      "text": "ꘅ Local Decision · choose a palette\n\nEdit the scene description, then press TOP Run. Inference starts only on that action.",
      "target": {
        "nodeType": "GeneretiCoreDecision",
        "nodeId": 2,
        "ref": "5d3efd43-da44-5d82-b995-8415c5f99cc3",
        "part": "parameter"
      },
      "hint": "Follow the note at the top of the workflow. Top Run updates connected nodes."
    },
    {
      "title": "Follow the typed control",
      "text": "ꘅ Choice to Value · palette label → hue\n\nThe choice label maps to 210 or 30. That numeric wire drives the p5 hue parameter.",
      "target": {
        "nodeType": "GeneretiCoreChoiceValue",
        "nodeId": 3,
        "ref": "0d714886-6129-569c-96dc-ea5482f65e7c",
        "part": "node"
      },
      "hint": "Follow the note at the top of the workflow. Top Run updates connected nodes."
    },
    {
      "title": "Inspect the answer",
      "text": "ꘅ Text / JSON Viewer · Model scores · inspect the choice\n\nRead the scores and compare the artwork. Try a different prompt; no model-written code is evaluated.",
      "target": {
        "nodeType": "GeneretiCoreResult",
        "nodeId": 5,
        "ref": "92ca4cf4-a71a-5dc5-9f96-e98d2db19cdd",
        "part": "node"
      },
      "hint": "Follow the note at the top of the workflow. Top Run updates connected nodes."
    }
  ]
}

